; forgot.asm -- chapter 17: WHERE IT BREAKS: a routine that does not read the status
; generated by gen17.py
        INCLUDE "msx.inc"
        OUTPUT "forgot.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
turns   EQU RESULTS             ; turns of the main loop
band    EQU RESULTS + 2         ; the border's colour
; WHERE IT BREAKS. The routine changes the colour of the border and returns,
; and never reads the status. The display is off: the border is the screen.
init:   di
        ld sp, SYS_AREA
        ld hl, 0
        ld (turns), hl
        ld a, BLACK
        ld (band), a
        VDP_REG 7, BLACK
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        VDP_REG 1, $A0          ; display off, and the frame's signal on
        in a, (VDP_CTRL)        ; no signal left over from before
        ei
main:   ld hl, (turns)
        inc hl
        ld (turns), hl          ; the main loop counts its turns
        jr main

; isr: the border in the other colour. It does not read the status.
isr:    push af
        ld a, (band)
        xor BLACK ^ LIGHT_GREEN
        ld (band), a
        out (VDP_CTRL), a
        ld a, $87               ; register 7: the border
o1:     out (VDP_CTRL), a
        pop af
        ei
        ret
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
